ALTER TABLE clinic_schedule ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'OPEN';
ALTER TABLE clinic_schedule ADD COLUMN stop_reason VARCHAR(200);
CREATE TABLE schedule_change(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenant(id),schedule_id BIGINT NOT NULL REFERENCES clinic_schedule(id),replacement_schedule_id BIGINT REFERENCES clinic_schedule(id),kind VARCHAR(20) NOT NULL,reason VARCHAR(200) NOT NULL,status VARCHAR(30) NOT NULL,actor_id BIGINT NOT NULL REFERENCES app_user(id),created_at TIMESTAMP NOT NULL,UNIQUE(tenant_id,schedule_id));
CREATE TABLE schedule_change_item(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenant(id),change_id BIGINT NOT NULL REFERENCES schedule_change(id),appointment_id BIGINT NOT NULL REFERENCES appointment(id),target_schedule_id BIGINT REFERENCES clinic_schedule(id),new_appointment_id BIGINT REFERENCES appointment(id),status VARCHAR(20) NOT NULL DEFAULT 'PENDING',decision VARCHAR(20) NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0,last_error VARCHAR(200),UNIQUE(change_id,appointment_id));
CREATE INDEX idx_change_pending ON schedule_change(status,id);
CREATE INDEX idx_change_items ON schedule_change_item(tenant_id,change_id,status,id);
